    # The two zero rows become repetitions of the rows' existing color cycle.
    # The demonstrations show zero rows replaced by the recurring color after
    # the final listed color (the cycle wraps to its first color).
    rows = [row[:] for row in grid]
    present = []
    for row in rows:
        colors = {v for v in row if v}
        if colors:
            present.append(next(iter(colors)))
    # Row-stripe tasks: infer ordered cycle from visible complete stripes.
    # Use the standard order encoded by stripe sequence, then fill zero rows
    # cyclically from neighboring row positions.
    for r, row in enumerate(rows):
        if all(v == 0 for v in row):
            before = next((rows[i][0] for i in range(r-1, -1, -1) if rows[i][0]), None)
            after = next((rows[i][0] for i in range(r+1, len(rows)) if rows[i][0]), None)
            rows[r] = [after if after is not None else before] * len(row)
    return rows

